#!/usr/bin/env bash
# The Rust math grammar (core/native/src/mathgrammar/) against its reference
# implementation, which runs in node. Two kinds of proof:
#
#   - the committed golden files (tests/mathgrammar/golden/) are the
#     reference's own output: the reference copies are the ones recorded in
#     tests/mathgrammar/README.md, and regenerating each golden file from them
#     gives the committed bytes. The Rust tests (cargo test, which needs
#     neither node nor a JSON crate) compare against those files.
#   - fresh random corpora, different on every run, are generated by the
#     reference (with deviations D5 to D11, tests/mathgrammar/README.md) and
#     compared with the Rust grammar field by field (the extracted text,
#     every math, the prepared TeX, the KaTeX and the MathJax text), so the
#     committed files are not the only thing the port is held to. Five
#     kinds: general documents (fuzz), documents dense in numbered
#     environments, tags, skip words, labels and references, comments,
#     row breaks and take-outs in them (ams, deviations D9 to D11),
#     documents of bare environments that repeat names (envs), displays
#     dense in what the KaTeX \newcommand rule reads (d5), and documents
#     dense in numbered multline environments and tags with groups
#     (multline, deviations D7 and D8).
#
#   bash tests/mathgrammar_spec.sh
#
#   JNV_KATEX_DIR=<dir>  an unpacked katex package (the folder that holds
#                        dist/katex.mjs): also check that
#                        tests/mathgrammar/katex_only.txt is what KaTeX and LaTeX
#                        give today; JNV_LATEX names the latex binary (without
#                        a latex that runs, only the KaTeX half is checked)
#   JNV_MATH_SEED=<n>    replay one corpus (the run prints its seed and count)
#   JNV_MATH_COUNT=<n>   documents in each fresh corpus (default 20000)
#   JNV_MATHGRAMMAR_STALL_SECS=<n>
#                        seconds with no document finished after which the
#                        comparison is declared stuck (default 120); that
#                        fails the check instead of stalling the suite
#   JNV_MATHGRAMMAR_NODE_SECS=<n>
#                        seconds one node run may take (default 300)
#   JNV_MATHGRAMMAR_CARGO_SECS=<n>
#                        seconds the cargo test of the fresh corpora may take,
#                        build included (default 1800)
#
# node is a test dependency: without it this spec fails, it never skips.
set -u
source "$(dirname "$0")/lib/test_env.sh"
ROOT="$JNV_REPO"

fails=0
# chk NAME RC [DETAIL]: one result line; a failure carries its detail.
chk() {
  if [ "$2" = 0 ]; then
    echo "  ok $1"
  else
    echo "FAIL $1${3:+  -- $3}"
    fails=$((fails + 1))
  fi
}

if ! command -v node >/dev/null 2>&1; then
  echo "FAIL node is not installed (the reference grammar runs in node)"
  exit 1
fi

MG="$ROOT/tests/mathgrammar"
GOLDEN="$MG/golden"
# inside the run dir, which test_env.sh removes
D="$(mktemp -d "$TMPDIR/jnv_mathgrammar.XXXXXX")" || { echo "FAIL mktemp"; exit 1; }

# sha256 of a file, whichever tool the host has
sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" 2>/dev/null | awk '{print $1}'
  else
    shasum -a 256 "$1" 2>/dev/null | awk '{print $1}'
  fi
}

# seconds, a whole number of at most 6 digits, else the default
secs_or() {
  case "${1:-}" in '' | *[!0-9]*) echo "$2" ;; *) [ "${#1}" -le 6 ] && [ "$1" -gt 0 ] && echo "$((10#$1))" || echo "$2" ;; esac
}
NODE_SECS="$(secs_or "${JNV_MATHGRAMMAR_NODE_SECS:-}" 300)"
CARGO_SECS="$(secs_or "${JNV_MATHGRAMMAR_CARGO_SECS:-}" 1800)"

# node under a deadline: the process is replaced by node, and the alarm survives
# the exec, so a node that hangs ends the step instead of the suite.
node_capped() {
  perl -e 'alarm shift; exec @ARGV' "$NODE_SECS" node "$@"
}

# sha_lines README DIR FILE...: every FILE of DIR has a "<file> sha256 <hex>"
# line in README and the file has that hash. Prints what is wrong, empty if all is well.
sha_lines() {
  local readme="$1" dir="$2" f want got bad=""
  shift 2
  if [ ! -f "$readme" ]; then
    echo " ${readme#"$ROOT"/} is missing;"
    return
  fi
  for f in "$@"; do
    want="$(awk -v f="$f" '$1 == f && $2 == "sha256" && NF == 3 {print $3}' "$readme" 2>/dev/null)"
    got="$(sha256_of "$dir/$f")"
    if [ ! -f "$dir/$f" ]; then
      bad="$bad ${dir#"$ROOT"/}/$f is missing;"
    elif [ -z "$want" ]; then
      bad="$bad $f has no sha256 line in ${readme#"$ROOT"/};"
    elif [ "$got" != "$want" ]; then
      bad="$bad $f is $got, the README records $want;"
    fi
  done
  printf '%s' "$bad"
}

# 1. the reference copies and the fixtures are the ones the READMEs record
bad="$(sha_lines "$MG/README.md" "$MG" mathgrammar.mjs katex_macros.mjs)"
[ -z "$bad" ]; chk "the reference copies match the sha256 in tests/mathgrammar/README.md" $? "${bad# }"
FIX="$ROOT/tests/fixtures/markdown"
bad="$(sha_lines "$FIX/README.md" "$FIX" md-fixture.md md-fixture.ipynb hero.md hero.ipynb gauss.md gauss.ipynb math_battery_cases.json)"
[ -z "$bad" ]; chk "the fixtures match the sha256 in tests/fixtures/markdown/README.md" $? "${bad# }"

# 2 to 5. each golden file is what the reference generates today
# golden_check NAME FILE ARGS...: gen_cases.mjs ARGS (run from the repo root,
# as the README gives them) must write FILE's committed bytes.
golden_check() {
  local name="$1" file="$2" rc detail="" where
  shift 2
  ( cd "$ROOT" && node_capped tests/mathgrammar/gen_cases.mjs "$@" ) > "$D/$file" 2> "$D/$file.err"
  rc=$?
  if [ "$rc" != 0 ]; then
    detail="gen_cases.mjs exited $rc: $(head -n 3 "$D/$file.err" | tr '\n' ' ')"
  elif [ ! -f "$GOLDEN/$file" ]; then
    rc=1
    detail="tests/mathgrammar/golden/$file is missing"
  elif ! cmp -s "$D/$file" "$GOLDEN/$file"; then
    rc=1
    where="$(cmp "$D/$file" "$GOLDEN/$file" 2>&1 | head -n 1)"
    case "$where" in
      # "<a> <b> differ: char N, line M"
      *" differ: "*) where="${where#* differ: }" ;;
      # one file ends inside the other ("cmp: EOF on <file>", which says no more)
      *) where="$(( $(wc -c < "$D/$file") )) bytes regenerated, $(( $(wc -c < "$GOLDEN/$file") )) committed" ;;
    esac
    detail="regenerated $file differs from the committed one ($where)"
  fi
  chk "$name" "$rc" "$detail"
}

golden_check "golden battery.cases is the reference's output" battery.cases \
  battery tests/fixtures/markdown/math_battery_cases.json
golden_check "golden additions.cases is the reference's output" additions.cases \
  battery tests/mathgrammar/battery_additions.json
golden_check "golden fixtures.cases is the reference's output" fixtures.cases \
  fixtures tests/fixtures/markdown
# the generated files hold seed 1; the last line is `count <n>`
for kind in fuzz ams envs d5 multline; do
  kind_count="$(tail -n 1 "$GOLDEN/$kind.cases" 2>/dev/null | awk '$1 == "count" && NF == 2 && $2 ~ /^[0-9]+$/ {print $2}')"
  if [ -n "$kind_count" ]; then
    golden_check "golden $kind.cases is the reference's output (seed 1, $kind_count documents)" "$kind.cases" \
      "$kind" 1 "$kind_count"
  else
    chk "golden $kind.cases is the reference's output (seed 1)" 1 "no 'count <n>' last line in golden/$kind.cases"
  fi
done
golden_check "golden tags.cases is the reference's output" tags.cases tags
golden_check "golden js_whitespace.txt is the reference's output" js_whitespace.txt whitespace

# 5b. the KaTeX names of the \newcommand rule (deviation D5). The Rust table is generated from the
# committed list; the list is what KaTeX and LaTeX give, which needs an unpacked katex package
# (JNV_KATEX_DIR) and, for the LaTeX half, a LaTeX with amsmath and amssymb (JNV_LATEX, default
# latex). The check compares the names and the `# katex` and `# katex-names` lines of the header: a
# different `# latex` banner (another TeX Live) is a note, and where the latex binary cannot run
# the KaTeX half alone is checked, with a note, so a machine without TeX Live passes it.
( cd "$ROOT" && node_capped tests/mathgrammar/gen_katex_only.mjs rust < tests/mathgrammar/katex_only.txt ) > "$D/katex_names.rs" 2> "$D/katex_names.err"
rc=$?
if [ "$rc" = 0 ] && ! cmp -s "$D/katex_names.rs" "$ROOT/core/native/src/mathgrammar/katex_names.rs"; then
  rc=1
  detail="katex_names.rs is not what gen_katex_only.mjs makes of katex_only.txt"
else
  detail="gen_katex_only.mjs exited $rc: $(head -n 3 "$D/katex_names.err" | tr '\n' ' ')"
fi
chk "core/native/src/mathgrammar/katex_names.rs is generated from tests/mathgrammar/katex_only.txt" "$rc" "$detail"
# the oracle of the rule against rows written out by hand (not derived from the Rust code)
out="$(cd "$ROOT" && node_capped tests/mathgrammar/katex_rule.mjs --self-test 2>&1)"
chk "tests/mathgrammar/katex_rule.mjs gives the hand-written rows of the D5 rule" $? "$(printf '%s' "$out" | head -n 3 | tr '\n' ' ')"
if [ -n "${JNV_KATEX_DIR:-}" ]; then
  out="$(cd "$ROOT" && node_capped tests/mathgrammar/gen_katex_only.mjs check "$JNV_KATEX_DIR" "${JNV_LATEX:-latex}" 2>&1)"
  chk "tests/mathgrammar/katex_only.txt is what KaTeX and LaTeX give (JNV_KATEX_DIR=$JNV_KATEX_DIR)" $? "$(printf '%s' "$out" | head -n 3 | tr '\n' ' ')"
  printf '%s\n' "$out" | grep '^note:' | sed 's/^/  /'
else
  echo "  note katex_only.txt is compared with KaTeX and LaTeX only when JNV_KATEX_DIR names an unpacked katex package (not set)"
fi

# 6. a fresh corpus the Rust grammar has not been shaped by
# whole_number VALUE: one to ten decimal digits
whole_number() {
  case "$1" in '' | *[!0-9]*) return 1 ;; esac
  [ "${#1}" -le 10 ]
}

# fresh_marker_in OUTPUT COUNT: the test said all COUNT documents are identical.
# With --nocapture libtest writes the line either alone (the test threads run
# in parallel) or after "test <name> ... " (one test thread: RUST_TEST_THREADS=1,
# or a host where Rust sees a single cpu).
fresh_marker_in() {
  printf '%s\n' "$1" | grep -qE "(^|[.]{3} )MATHGRAMMAR FRESH $2 DOCUMENTS IDENTICAL\$"
}

# the reader finds the marker in both layouts and in nothing near it
shape_alone=$'running 1 test\nMATHGRAMMAR FRESH 70 DOCUMENTS IDENTICAL\ntest fresh_cases_from_env ... ok'
shape_inline=$'running 1 test\ntest fresh_cases_from_env ... MATHGRAMMAR FRESH 70 DOCUMENTS IDENTICAL\nok'
shape_off=$'MATHGRAMMAR FRESH 700 DOCUMENTS IDENTICAL\nx MATHGRAMMAR FRESH 70 DOCUMENTS IDENTICAL\nMATHGRAMMAR FRESH 70 DOCUMENTS IDENTICAL x\nMATHGRAMMAR FRESH 7 DOCUMENTS IDENTICAL'
fresh_marker_in "$shape_alone" 70 && fresh_marker_in "$shape_inline" 70 && ! fresh_marker_in "$shape_off" 70
chk "the fresh corpus marker is read from both layouts of libtest's output" $?

# The system's tool path: an active conda env puts its own cc and ld first on PATH
# and exports compiler variables for them, and that linker cannot read this
# system's SDK, so a rebuild fails with "symbol(s) not found". Cargo runs without
# those variables and without the env's bin directories (tests/native_screen.sh
# does the same for its compile).
sys_path() {
  local d out="" IFS=:
  for d in $PATH; do
    case "$d" in
      "${CONDA_PREFIX:-/no conda prefix}"/*|*/conda*/*|*/miniconda*/*|*/anaconda*/*|*/miniforge*/*|*/mambaforge*/*) ;;
      *) out="${out:+$out:}$d" ;;
    esac
  done
  printf '%s' "$out"
}

seed="${JNV_MATH_SEED:-$(( ($(date +%s) * 7919 + $$) % 2147483647 ))}"
count="${JNV_MATH_COUNT:-20000}"
if ! whole_number "$seed" || ! whole_number "$count"; then
  chk "a fresh random corpus is identical" 1 "JNV_MATH_SEED and JNV_MATH_COUNT must be whole numbers of at most 10 digits"
else
  # 007 is the number 7 to node and to the test, so it is 7 here too
  seed=$((10#$seed))
  count=$((10#$count))
  if [ "$count" = 0 ]; then
    chk "a fresh random corpus is identical" 1 "JNV_MATH_COUNT must be at least 1"
  else
    echo "  seed $seed, $count documents of each kind (replay: JNV_MATH_SEED=$seed JNV_MATH_COUNT=$count bash tests/mathgrammar_spec.sh)"
    CARGO_PATH="$(sys_path)"
    for kind in fuzz ams envs d5 multline; do
      name="a fresh $kind corpus (seed $seed, $count documents) is identical"
      node_capped "$MG/gen_cases.mjs" "$kind" "$seed" "$count" > "$D/fresh-$kind.cases" 2> "$D/gen-$kind.err"
      rc=$?
      if [ "$rc" != 0 ]; then
        chk "$name" 1 "gen_cases.mjs exited $rc: $(head -n 3 "$D/gen-$kind.err" | tr '\n' ' ')"
      else
        out="$(cd "$ROOT/core" && JNV_MATHGRAMMAR_CASES="$D/fresh-$kind.cases" \
          env -u CC -u CXX -u LD -u LDFLAGS -u CFLAGS -u CPPFLAGS -u SDKROOT -u CONDA_BUILD_SYSROOT -u AR \
          PATH="$CARGO_PATH" \
          perl -e 'alarm shift; exec @ARGV' "$CARGO_SECS" \
          cargo test --release --test math_grammar -- --exact fresh_cases_from_env --nocapture 2>&1)"
        rc=$?
        if [ "$rc" = 0 ] && fresh_marker_in "$out" "$count"; then
          chk "$name" 0
        else
          chk "$name" 1 "cargo test exited $rc; last 40 lines follow"
          printf '%s\n' "$out" | tail -n 40
        fi
      fi
    done
  fi
fi

if [ "$fails" = 0 ]; then
  echo "ALL MATH GRAMMAR CHECKS PASSED"
  exit 0
fi
echo "$fails MATH GRAMMAR CHECKS FAILED"
exit 1
